import React, { useEffect, useRef, useState, useCallback } from 'react';

interface ExamInfo {
  target_sequence: string[];
  current_target_digit: string | null;
  correct_count: number;
  total_targets: number;
  time_elapsed: number;
  running: boolean;
  feedback: string;
  exam_finished: boolean;
}

interface ChallengeInfo {
  is_challenge_mode: boolean;
  target_string: string;
  current_word_index: number;
  current_char_target_sequence: string[];
  current_char_next_digit_index: number;
  is_error_locked: boolean;
}

interface CorrectionData {
    target_signal: string | null;
    target_l_angle: number | null;
    target_r_angle: number | null;
    l_angle_diff: number | null;
    r_angle_diff: number | null;
    l_angle_ok: boolean;
    r_angle_ok: boolean;
    l_arm_straight_ok: boolean;
    r_arm_straight_ok: boolean;
    is_correct: boolean;
}

interface DetectionData {
  left_angle: number | null;
  right_angle: number | null;
  current_digit: number | string | null;
  sequence: string[];
  display_result: string | null;
  state: string;
  prompt_code: string | null;
  l_arm_status: string;
  r_arm_status: string;
  timer: number;
  target_person_bbox: number[] | null;
  flag_boxes: number[][];
  mode: string;
  exam_info: ExamInfo;
  cross_count: number;
  word_history: string[];
  challenge_info: ChallengeInfo;
  correction_data: CorrectionData;
  gesture_angle_threshold: number;
  gesture_cross_threshold: number;
}

const promptMessages: { [key: string]: (data: DetectionData) => string } = {
    'WAITING_FOR_PERSON': () => '等待人出現...',
    'GESTURE_START_PROMPT': () => '請舉起雙手交叉以啟動',
    'AWAITING_HIGH_WAVE': (data) => `請向上揮動，手肘可微彎 (${data.cross_count}/${data.gesture_cross_threshold})`,
    'AWAITING_CROSS': (data) => `請交叉/打開手腕 (${data.cross_count}/${data.gesture_cross_threshold || 3})`,
    'AWAITING_LOW_WAVE': (data) => `請伸直雙手，向下揮動 (${data.cross_count}/${data.gesture_cross_threshold})`,
    'GESTURE_COMPLETE': (data) => `手勢完成！請放下雙手以${data.state === 'IDLE' ? '開始' : '重置'}`,
    'SYSTEM_ACTION_TRIGGERED': (data) => `收到指令，系統${data.state === 'IDLE' ? '開始' : '重置'}！`,
    'PRACTICE_WAITING': () => '請做出 [雙手放下] 的準備姿勢',
    'PRACTICE_READY': () => '準備就緒，請開始動作',
    'PRACTICE_DETECTING': (data) => `偵測到指令 ${data.current_digit}，請保持穩定...`,
    'PRACTICE_ARMS_NOT_STRAIGHT': () => '姿勢無效或手臂未伸直',
    'PRACTICE_COOLDOWN': () => '成功！請放下雙手，準備下一個信號',
    'DELETED_LAST_DIGIT': () => '已刪除上一個信號',
    'DELETED_LAST_WORD': () => '已刪除上一個文字',
};

const getPromptText = (data: DetectionData | null): string => {
    if (!data || !data.prompt_code) {
        return '-';
    }
    const messageFunc = promptMessages[data.prompt_code];
    if (messageFunc) {
        return messageFunc(data);
    }
    // Fallback for dynamic strings sent directly from backend
    return data.prompt_code;
};


const VideoStream: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const [detectionData, setDetectionData] = useState<DetectionData | null>(null);
  const [currentMode, setCurrentMode] = useState<string>('practice');
  const [currentSystem, setCurrentSystem] = useState<string>('chinese');
  // New state for Correction Mode
  const [correctionTarget, setCorrectionTarget] = useState<string | null>(null);
  const [isFlagRequired, setIsFlagRequired] = useState<boolean>(true);
  const [examTargetSequence, setExamTargetSequence] = useState<string>('1234');
        const [backendError, setBackendError] = useState<string | null>(null);
        const [isLoading, setIsLoading] = useState<boolean>(true);
        const [isMirrored, setIsMirrored] = useState(true); // New state for mirroring video
  // Updated states for Challenge Mode
  const [isChallengeEnabled, setIsChallengeEnabled] = useState<boolean>(false);
  const [challengeString, setChallengeString] = useState<string>('');


  const sendMessage = useCallback((command: string, payload?: any) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ command, payload }));
    }
  }, []);

  useEffect(() => {
    setIsLoading(true); 
    const ws = new WebSocket('ws://localhost:8000/ws');
    wsRef.current = ws;

    ws.onopen = () => {
      console.log('WebSocket Connected');
      setBackendError(null);
      sendMessage('set_mode', { mode: currentMode, system: currentSystem, target_sequence: examTargetSequence.split('') });
      sendMessage('set_video_source', { source: '0' });
      setIsLoading(false);
    };

    ws.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data);

        if (payload.error) {
          setBackendError(payload.error);
          setIsLoading(false);
          setDetectionData(null);
          const canvas = canvasRef.current;
          if (canvas) {
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.clearRect(0, 0, canvas.width, canvas.height);
            }
          }
          return;
        }

        if (payload.status) {
          console.log("Backend Status:", payload.status);
          setBackendError(null);
          setIsLoading(true);
          return;
        }

        setBackendError(null);
        setIsLoading(false);
        const data = payload.data;
        setDetectionData(data);

        const canvas = canvasRef.current;
        if (canvas) {
          const ctx = canvas.getContext('2d');
          if (ctx) {
            const img = new Image();
            img.onload = () => {
              canvas.width = img.width;
              canvas.height = img.height;
              ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
            };
            img.src = `data:image/jpeg;base64,${payload.image}`;
          }
        }
      } catch (error) {
        console.error('Failed to parse WebSocket message:', error);
        setBackendError(`Failed to parse message from backend: ${error}`);
        setIsLoading(false);
      }
    };

    ws.onclose = () => {
      console.log('WebSocket Disconnected');
      setIsLoading(false);
      setBackendError("WebSocket disconnected. Please ensure the backend server is running.");
    };

    ws.onerror = (error) => {
      console.error('WebSocket Error:', error);
      setIsLoading(false);
      setBackendError(`WebSocket error: ${error}`);
    };

    return () => {
      ws.close();
    };
  }, [sendMessage, currentMode, currentSystem, examTargetSequence, correctionTarget]);


  const handleModeChange = (mode: string) => {
    setIsLoading(true);
    setCurrentMode(mode);
    if (mode !== 'practice') {
      setIsChallengeEnabled(false);
      sendMessage('set_challenge_mode', { enabled: false });
    }
    // When switching away from correction mode, tell backend to clear the target
    if (mode !== 'correction') {
      sendMessage('set_correction_target', { signal: null });
      setCorrectionTarget(null); // Also clear frontend state
    }
    sendMessage('set_mode', { mode: mode, system: currentSystem, target_sequence: examTargetSequence.split('') });
  };

  const handleSystemChange = (system: string) => {
    setIsLoading(true);
    setCurrentSystem(system);
    // Reset challenge & correction mode on system switch to avoid mapping mismatch
    setIsChallengeEnabled(false);
    setChallengeString('');
    setCorrectionTarget(null);
    sendMessage('set_challenge_mode', { enabled: false });
    sendMessage('set_correction_target', { signal: null });
    sendMessage('set_mode', { mode: currentMode, system: system, target_sequence: examTargetSequence.split('') });
  };

  // New handler for setting the correction target
  const handleSetCorrectionTarget = (signal: string) => {
    if (currentMode === 'correction') {
      setCorrectionTarget(signal);
      sendMessage('set_correction_target', { signal: signal });
    }
  };

  const handleToggleChallengeMode = (e: React.ChangeEvent<HTMLInputElement>) => {
    const isEnabled = e.target.checked;
    setIsChallengeEnabled(isEnabled);
    // If the user is UNCHECKING the box, disable challenge mode on the backend.
    if (!isEnabled) {
      sendMessage('set_challenge_mode', { enabled: false, chars: null });
    }
  };

  const handleSetChallengeString = () => {
    if (isChallengeEnabled && challengeString) {
      sendMessage('set_challenge_mode', { enabled: true, chars: challengeString });
    }
  };

  const handleStartExam = () => {
    setIsLoading(true);
    sendMessage('start_exam');
  };

  const handleStopExam = () => {
    setIsLoading(true);
    sendMessage('stop_exam');
  };

  const handleFlagRequirementChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const isRequired = e.target.checked;
    setIsFlagRequired(isRequired);
    sendMessage('set_flag_requirement', { required: isRequired });
  };

  const challengeInfo = detectionData?.challenge_info;
  const correctionData = detectionData?.correction_data;

  // New unified logic for determining the hint image
  let hintImageSrc: string | null = null;
  const promptCode = detectionData?.prompt_code;
  const state = detectionData?.state;

  if (detectionData && promptCode) { 
    const nextDigit = challengeInfo?.is_challenge_mode &&
      challengeInfo.current_char_target_sequence.length > 0 &&
      challengeInfo.current_char_next_digit_index < challengeInfo.current_char_target_sequence.length
      ? challengeInfo.current_char_target_sequence[challengeInfo.current_char_next_digit_index]
      : null;

    // Highest priority: check for initial states before a user is even ready
    if (promptCode === "WAITING_FOR_PERSON" || promptCode.includes("尋找目標") || promptCode.includes("目標已鎖定")) {
      hintImageSrc = '/digits/start&end.png';
    }
    // State-specific images
    else if (promptCode === "PRACTICE_WAITING" || promptCode === "PRACTICE_COOLDOWN" || state === 'CORRECTED_SUCCESS') {
      hintImageSrc = '/digits/stay.png';
    }
    // Handle error state in challenge mode
    else if (challengeInfo?.is_challenge_mode && challengeInfo.is_error_locked) {
      if (state === 'READY') {
        hintImageSrc = '/digits/cancell.png'; // Once hands are down, show cancel
      } else {
        hintImageSrc = '/digits/stay.png'; // Guide to put hands down first
      }
    }
    // Handle end gesture for challenge completion
    else if (promptCode.includes("指定練習完成")) {
        hintImageSrc = '/digits/stay.png'; // Guide to put hands down first
    }
    else if (state === 'CHALLENGE_READY_TO_END') {
        hintImageSrc = '/digits/start&end.png'; // Now show the end gesture
    }
    // Start/End gesture (initial start or awaiting cross)
    else if (promptCode === "GESTURE_START_PROMPT" || promptCode === "AWAITING_CROSS") {
      hintImageSrc = '/digits/start&end.png';
    }
    // Hint for the next character in challenge mode OR correction mode
    else if (nextDigit !== null) {
      hintImageSrc = `/digits/${nextDigit}.png`;
    } 
    else if (state === 'CORRECTING' && correctionData?.target_signal) {
       hintImageSrc = `/digits/${correctionData.target_signal}.png`;
    }
  }

  const renderTargetString = () => {
    if (!challengeInfo || !challengeInfo.target_string) return null;

    return (
      <p>
        目標: {' '}
        {challengeInfo.target_string.split('').map((char, index) => (
          <strong 
            key={index} 
            style={{ 
              color: index === challengeInfo.current_word_index ? '#FFD700' : 'white',
              fontSize: '1.2em',
              margin: '0 2px'
            }}
          >
            {char}
          </strong>
        ))}
        {' ('}
        {challengeInfo.current_char_target_sequence.join(' ')}
        {')'}
      </p>
    );
  };


  const isDisconnected = backendError && (backendError.includes("WebSocket disconnected") || backendError.includes("WebSocket error"));

  const signalOptions = currentSystem === 'chinese' 
    ? Array.from({ length: 10 }, (_, i) => i.toString())
    : "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '10px', backgroundColor: '#282c34', color: 'white', minHeight: '100vh' }}>
      <h1>旗語姿態偵測與校正系統</h1>

      {backendError && !isDisconnected && (
        <div style={{ color: '#FF4C6C', fontWeight: 'bold', marginBottom: '20px', border: '2px solid #FF4C6C', padding: '10px', borderRadius: '5px' }}>
          Backend Error: {backendError}
        </div>
      )}

      {isDisconnected ? (
        <div style={{
          position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', 
          backgroundColor: 'rgba(0, 0, 0, 0.9)', color: 'white', display: 'flex',
          flexDirection: 'column', justifyContent: 'center', alignItems: 'center',
          zIndex: 1000, textAlign: 'center', fontSize: '1.5em', padding: '20px'
        }}>
          <h2>連線已中斷</h2>
          <p>{backendError}</p>
          <button onClick={() => window.location.reload()} style={{ marginTop: '20px', padding: '15px 30px', fontSize: '1em', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>
            重新整理頁面
          </button>
        </div>
      ) : (
        <>
          {/* TOP: Control Panel */}
          <div style={{ width: '100%', maxWidth: '1600px', padding: '15px', backgroundColor: '#333', borderRadius: '8px', marginBottom: '20px' }}>
            <div style={{ display: 'flex', gap: '20px' }}>

              {/* Column 1: Mode & System */}
              <div style={{ flex: 1 }}>
                <h3>主要模式</h3>
                <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
                  <button onClick={() => handleModeChange('practice')} style={{ padding: '10px', backgroundColor: currentMode === 'practice' ? '#007bff' : '#6c757d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1, fontSize: '1em', fontWeight: 'bold' }}>練習</button>
                  <button onClick={() => handleModeChange('correction')} style={{ padding: '10px', backgroundColor: currentMode === 'correction' ? '#ffc107' : '#6c757d', color: 'black', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1, fontSize: '1em', fontWeight: 'bold' }}>校正</button>
                  <button onClick={() => handleModeChange('exam')} style={{ padding: '10px', backgroundColor: currentMode === 'exam' ? '#dc3545' : '#6c757d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1, fontSize: '1em', fontWeight: 'bold' }}>考試</button>
                </div>
                <h4 style={{ margin: '15px 0 10px 0', color: '#ccc' }}>旗語系統</h4>
                <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
                  <button onClick={() => handleSystemChange('chinese')} style={{ padding: '10px', backgroundColor: currentSystem === 'chinese' ? '#17a2b8' : '#6c757d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1 }}>中文數字</button>
                  <button onClick={() => handleSystemChange('navy')} style={{ padding: '10px', backgroundColor: currentSystem === 'navy' ? '#28a745' : '#6c757d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1 }}>海軍英文</button>
                </div>
              </div>

              {/* Column 2: Options */}
              <div style={{ flex: 2, borderLeft: '1px solid #555', paddingLeft: '20px' }}>
                <h3>選項</h3>
                 {currentMode === 'practice' && (
                  <div style={{ padding: '10px', border: '1px solid #555', borderRadius: '8px', backgroundColor: '#3a3f47' }}>
                    <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', fontSize: '1.1em' }}>
                      <input type="checkbox" checked={isChallengeEnabled} onChange={handleToggleChallengeMode} style={{ width: '20px', height: '20px', marginRight: '10px' }} />
                      指定字串練習
                    </label>
                    {isChallengeEnabled && (
                      <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                        <input type="text" placeholder={currentSystem === 'chinese' ? "輸入想練習的中文" : "輸入想練習的英文 (A-Z)"} value={challengeString} onChange={(e) => setChallengeString(currentSystem === 'navy' ? e.target.value.toUpperCase() : e.target.value)} style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', color: 'black', flex: 1, fontSize: '1em' }}/>
                        <button onClick={handleSetChallengeString} disabled={!challengeString} style={{ padding: '10px 20px', backgroundColor: '#17a2b8', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold' }}>設定</button>
                      </div>
                    )}
                  </div>
                )}
                {currentMode === 'correction' && (
                   <div style={{ padding: '10px', border: '1px solid #555', borderRadius: '8px', backgroundColor: '#3a3f47' }}>
                      <label htmlFor="correction-select" style={{ fontSize: '1.1em', marginRight: '10px' }}>選擇要校正的信號:</label>
                      <select id="correction-select" value={correctionTarget || ''} onChange={(e) => handleSetCorrectionTarget(e.target.value)} style={{padding: '10px', fontSize: '1.1em', borderRadius: '5px'}}>
                        <option value="" disabled>-- 請選擇 --</option>
                        {signalOptions.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                   </div>
                )}
                 {currentMode === 'exam' && (
                  <div style={{ padding: '10px', border: '1px solid #555', borderRadius: '8px' }}>
                    <h4>(功能開發中)</h4>
                  </div>
                )}
              </div>

              {/* Column 3: Global Settings */}
              <div style={{ flex: 1, borderLeft: '1px solid #555', paddingLeft: '20px' }}>
                <h3>全域設定</h3>
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', fontSize: '1.1em', marginBottom: '15px' }}>
                    <input type="checkbox" checked={isFlagRequired} onChange={handleFlagRequirementChange} style={{ width: '20px', height: '20px', marginRight: '10px' }} />
                    需要旗幟進行目標鎖定
                </label>
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', fontSize: '1.1em' }}>
                    <input type="checkbox" checked={isMirrored} onChange={() => setIsMirrored(!isMirrored)} style={{ width: '20px', height: '20px', marginRight: '10px' }} />
                    鏡像畫面 (Mirror Video)
                </label>
              </div>
            </div>
          </div>

          {/* BOTTOM: Video and Info */}
          <div style={{ display: 'flex', gap: '20px', width: '100%', maxWidth: '1600px' }}>
            {/* Video Stream Box */}
            <div style={{ flex: '2 1 0', border: '1px solid #444', borderRadius: '8px', overflow: 'hidden', position: 'relative' }}>
              {isLoading && (
                <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '2em' }}>
                  Loading Video Stream...
                </div>
              )}
              <canvas ref={canvasRef} style={{ width: '100%', height: 'auto', display: 'block', transform: isMirrored ? 'scaleX(-1)' : 'none' }} />
            </div>

            {/* RIGHT PANEL (Detection Info) */}
            <div style={{ flex: '1 1 0', backgroundColor: '#333', padding: '20px', borderRadius: '8px', textAlign: 'left', display: 'flex', flexDirection: 'column' }}>
              <h2>即時資訊</h2>
              <hr style={{ borderColor: '#555', margin: '10px 0 20px 0' }} />

              {detectionData ? (
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                  {/* Top-aligned info */}
                  <div>
                    <p style={{ fontSize: '1.2em', margin: 0 }}><strong>提示:</strong> <span style={{ color: '#FF4C6C', fontWeight: 'bold', fontSize: '1.5em', display: 'block', margin: '10px 0', minHeight: '3em', lineHeight: '1.5em' }}>{getPromptText(detectionData)}</span></p>
                    {isChallengeEnabled && renderTargetString()}
                  </div>

                  {/* Bottom-aligned content */}
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                     <div style={{ padding: '10px', backgroundColor: '#444', borderRadius: '8px', textAlign: 'center' }}>
                      <h4>提示圖片</h4>
                      {hintImageSrc ? (
                        <img src={hintImageSrc} alt="Hint" style={{ maxHeight: '200px', width: 'auto', maxWidth: '100%' }} />
                      ) : (
                        <p>無</p>
                      )}
                    </div>
                     <hr style={{ borderColor: '#555', width: '100%' }} />
                     {currentMode === 'correction' && correctionData?.target_signal ? (
                       <div>
                         <p>左臂角度: {detectionData.left_angle?.toFixed(0)}° (目標: {correctionData.target_l_angle}°)</p>
                         <p>右臂角度: {detectionData.right_angle?.toFixed(0)}° (目標: {correctionData.target_r_angle}°)</p>
                         <p>左臂伸直: {correctionData.l_arm_straight_ok ? '✔️' : '❌'}</p>
                         <p>右臂伸直: {correctionData.r_arm_straight_ok ? '✔️' : '❌'}</p>
                       </div>
                     ) : (
                       <div>
                        <p style={{ margin: '0 0 8px 0' }}><strong>偵測狀態:</strong> {detectionData.state}</p>
                        <p style={{ margin: '0 0 8px 0' }}><strong>左右手角度:</strong> 左: {detectionData.left_angle !== null ? detectionData.left_angle.toFixed(1) : 'N/A'} 右: {detectionData.right_angle !== null ? detectionData.right_angle.toFixed(1) : 'N/A'}</p>
                        <p style={{ margin: '0 0 8px 0' }}><strong>左右手伸直:</strong> 左: {detectionData.l_arm_status} 右: {detectionData.r_arm_status}</p>
                        <p style={{ margin: '0 0 8px 0' }}><strong>揮手計數:</strong> <span style={{ color: '#FFD700' }}>{detectionData.cross_count}</span></p>
                        {currentMode === 'practice' && (
                          <>
                            <p style={{ margin: '0 0 8px 0' }}><strong>目前序列:</strong> {detectionData.sequence.join(' ')}</p>
                            <p style={{ margin: '0 0 8px 0' }}><strong>辨識結果:</strong> {detectionData.display_result || 'N/A'}</p>
                          </>
                        )}
                        <p style={{ margin: '0 0 8px 0' }}><strong>歷史記錄:</strong> <span style={{ letterSpacing: '2px', wordBreak: 'break-all' }}>
                          {detectionData.word_history && detectionData.word_history.length > 0 
                            ? detectionData.word_history.join(' ') 
                            : '暫無歷史記錄'}
                        </span></p>
                       </div>
                     )}
                  </div>
                </div>
              ) : (
                <p>等待後端資料...</p>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default VideoStream;
